/** 
 * Performs a right node rotation.
 * @param node a node to rotate
 * @return a new parent of the {@code node}
 */
private TreeNode<T> rotateRight(TreeNode<T> node) {
    // The new root of the subtree will be the current node's left child
    TreeNode<T> newRoot = node.left;

    // The current node's left child will be the new root's right child
    node.left = newRoot.right;

    // The new root's right child will be the current node
    newRoot.right = node;

    // Return the new root of the subtree
    return newRoot;
}

