import java.text.SimpleDateFormat;
import java.util.Date;

public class LogFormatter {

    private static final String CONVERSION_PATTERN = "%d{yyyy-MM-dd HH:mm:ss} [%p] %m";

    /**
     * Produces a formatted string as specified by the conversion pattern.
     */
    public String format(LoggingEvent event) {
        StringBuilder formattedMessage = new StringBuilder();

        String pattern = CONVERSION_PATTERN;
        int length = pattern.length();
        for (int i = 0; i < length; i++) {
            char c = pattern.charAt(i);
            if (c == '%') {
                i++; // Move to the next character which is the format specifier
                if (i < length) {
                    c = pattern.charAt(i);
                    switch (c) {
                        case 'd': // Date
                            formattedMessage.append(new SimpleDateFormat("yyyy-MM-dd HH:mm:ss").format(new Date(event.getTimeStamp())));
                            break;
                        case 'p': // Log level
                            formattedMessage.append(event.getLevel());
                            break;
                        case 'm': // Log message
                            formattedMessage.append(event.getMessage());
                            break;
                        default:
                            formattedMessage.append('%').append(c); // If not recognized, append as is
                            break;
                    }
                }
            } else {
                formattedMessage.append(c);
            }
        }

        return formattedMessage.toString();
    }
}

