public class TelnetServer {
    private final List<PrintWriter> clients;

    public TelnetServer(List<PrintWriter> clients) {
        this.clients = clients;
    }

    /** 
     * sends a message to each of the clients in telnet-friendly output. 
     */
    public synchronized void send(final String message){
        for (PrintWriter client : clients) {
            if (client != null) {
                client.println(message); // Telnet typically uses \r\n for new lines, but println should handle it.
                client.flush(); // Ensure the message is sent immediately.
            }
        }
    }
}

