        char ch = str.charAt(i);
        if (ch <= 0x7F) {
            size += 1;
        } else if (ch <= 0x7FF) {
            size += 2;
        } else if (Character.isHighSurrogate(ch)) {
            // High surrogate, check for low surrogate
            if (i + 1 < index + len && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4; // Full surrogate pair
                i++; // Skip the low surrogate
            } else {
                size += 3; // Unpaired high surrogate
            }
        } else {
            size += 3;
        }
    }
    return size;
}

