import java.util.Properties;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public static String findAndSubst(String key, Properties props) {
    // Find the value corresponding to the key in props
    String value = props.getProperty(key);
    if (value == null) {
        return null; // or throw an exception, or return an empty string, depending on your needs
    }

    // Define a pattern to match ${variable} placeholders
    Pattern pattern = Pattern.compile("\\$\\{([^}]+)\\}");
    Matcher matcher = pattern.matcher(value);

    // Use a StringBuffer to build the result with substitutions
    StringBuffer result = new StringBuffer();

    // Find each placeholder and replace it with the corresponding value from props
    while (matcher.find()) {
        String varName = matcher.group(1);
        String varValue = props.getProperty(varName);
        if (varValue != null) {
            matcher.appendReplacement(result, Matcher.quoteReplacement(varValue));
        } else {
            matcher.appendReplacement(result, matcher.group(0)); // keep the original placeholder if no value is found
        }
    }
    matcher.appendTail(result);

    return result.toString();
}

