@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type == Character.class || type == char.class) {
        if (value == null) {
            throw new IllegalArgumentException("Value cannot be null for conversion to Character.");
        }
        if (value instanceof Character) {
            return value;
        }
        if (value instanceof String) {
            String strValue = (String) value;
            if (strValue.length() == 1) {
                return strValue.charAt(0);
            } else {
                throw new IllegalArgumentException("String value must be of length 1 for conversion to Character.");
            }
        }
        if (value instanceof Number) {
            int intValue = ((Number) value).intValue();
            if (intValue >= Character.MIN_VALUE && intValue <= Character.MAX_VALUE) {
                return (char) intValue;
            } else {
                throw new IllegalArgumentException("Number value is out of range for conversion to Character.");
            }
        }
        throw new IllegalArgumentException("Unsupported value type for conversion to Character: " + value.getClass().getName());
    }
