/**
 * Removes any inactive nodes from the Category tree.
 */
protected int removeUnusedNodes() {
    return removeUnusedNodes(this);
}

private int removeUnusedNodes(Category node) {
    if (node == null) {
        return 0;
    }

    int removedCount = 0;

    // Iterate over the children and remove inactive ones
    List<Category> activeChildren = new ArrayList<>();
    for (Category child : node.getChildren()) {
        if (child.isActive()) {
            activeChildren.add(child);
        } else {
            removedCount++;
        }
    }
    node.setChildren(activeChildren);

    // Recursively remove unused nodes from the active children
    for (Category child : activeChildren) {
        removedCount += removeUnusedNodes(child);
    }

    return removedCount;
}

