final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
    // Calculate the offset of the CONSTANT_Utf8 entry in the classFileBuffer
    int offset = constantPoolEntryIndex * 8; // Assuming each entry is 8 bytes, adjust as necessary

    // Read the length of the UTF8 string
    int length = (classFileBuffer[offset] & 0xFF) << 8 | (classFileBuffer[offset + 1] & 0xFF);

    // Initialize a variable to track the position in the charBuffer
    int charBufferIndex = 0;

    // Read the UTF8 bytes and convert them to characters
    for (int i = 0; i < length; ) {
        int c = classFileBuffer[offset + 2 + i] & 0xFF;
        if (c > 127) {
            break;
        }
        charBuffer[charBufferIndex++] = (char) c;
        i++;
    }

    // Handle multi-byte UTF8 characters
    for (int i = 0; i < length; ) {
        int c = classFileBuffer[offset + 2 + i] & 0xFF;
        if (c < 128) {
            charBuffer[charBufferIndex++] = (char) c;
            i++;
        } else if ((c & 0xE0) == 0xC0) {
            charBuffer[charBufferIndex++] = (char) (((c & 0x1F) << 6) |
                                                   (classFileBuffer[offset + 2 + i + 1] & 0x3F));
            i += 2;
        } else if ((c & 0xF0) == 0xE0) {
            charBuffer[charBufferIndex++] = (char) (((c & 0x0F) << 12) |
                                                   ((classFileBuffer[offset + 2 + i + 1] & 0x3F) << 6) |
                                                   (classFileBuffer[offset + 2 + i + 2] & 0x3F));
            i += 3;
        } else {
            // Handle malformed UTF8 sequence
            throw new IllegalArgumentException("Malformed UTF8 sequence");
        }
    }

    // Return the string created from the charBuffer
    return new String(charBuffer, 0, charBufferIndex);
}

