protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour set cannot be null or empty");
    }

    // Create a map to track the next edge for each vertex
    Map<V, E> nextEdgeMap = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        if (nextEdgeMap.containsKey(source)) {
            throw new IllegalArgumentException("The provided edges do not form a valid tour");
        }
        nextEdgeMap.put(source, edge);
    }

    // Find a starting vertex (any vertex with an outgoing edge in the tour)
    V startVertex = nextEdgeMap.keySet().iterator().next();
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    V currentVertex = startVertex;

    // Traverse the tour to build the path
    do {
        vertexList.add(currentVertex);
        E currentEdge = nextEdgeMap.get(currentVertex);
        if (currentEdge == null) {
            throw new IllegalArgumentException("The provided edges do not form a valid tour");
        }
        edgeList.add(currentEdge);
        currentVertex = graph.getEdgeTarget(currentEdge);
    } while (!currentVertex.equals(startVertex));

    // Add the start vertex again to close the tour
    vertexList.add(startVertex);

    return new GraphWalk<>(graph, startVertex, startVertex, vertexList, edgeList, 0);
}

