int addConstantNameAndType(final String name, final String descriptor) {
    // Check if the constant pool already contains a similar item
    for (int i = 1; i < constantPool.size(); i++) {
        Symbol existingSymbol = constantPool.get(i);
        if (existingSymbol instanceof ConstantNameAndTypeSymbol) {
            ConstantNameAndTypeSymbol existingNameAndType = (ConstantNameAndTypeSymbol) existingSymbol;
            if (existingNameAndType.getName().equals(name) && existingNameAndType.getDescriptor().equals(descriptor)) {
                return i; // Return the index of the existing symbol
            }
        }
    }
    // If no similar item is found, add a new one
    ConstantNameAndTypeSymbol newSymbol = new ConstantNameAndTypeSymbol(name, descriptor);
    constantPool.add(newSymbol);
    return constantPool.size() - 1; // Return the index of the newly added symbol
}

