private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Get the bucket with the minimum label
    Set<Integer> minLabelBucket = bucketsByLabel.get(minLabel);

    // Get the bucket with label 0
    Set<Integer> zeroLabelBucket = bucketsByLabel.get(0);

    // Move all vertices from the minLabel bucket to the 0 label bucket
    zeroLabelBucket.addAll(minLabelBucket);

    // Clear the bucket with the minimum label
    minLabelBucket.clear();

    // Update the labels of the moved vertices to 0
    for (Integer vertex : zeroLabelBucket) {
        if (labels.get(vertex) == minLabel) {
            labels.set(vertex, 0);
        }
    }
}

