 * Remove the non null  {@code node} from the list. 
 */
private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> prev = node.prev;
    ListNodeImpl<E> next = node.next;

    if (prev == null) {
        // Node is the head of the list
        first = next;
    } else {
        prev.next = next;
        node.prev = null;
    }

    if (next == null) {
        // Node is the tail of the list
        last = prev;
    } else {
        next.prev = prev;
        node.next = null;
    }

    node.item = null; // Help GC
    size--;
    return true;
}
/** 
 * Remove the non null  {@code node} from the list. 
 */
private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }

    ListNodeImpl<E> next = node.next;

    if (node == first) {
        // Node is the head of the list
        first = next;
    } else {
        // Find the previous node
        ListNodeImpl<E> current = first;
        while (current != null && current.next != node) {
            current = current.next;
        }
        if (current != null) {
            current.next = next;
        }
    }

    if (node == last) {
        // Node is the tail of the list
        last = current;
    }

    node.next = null; // Help GC
    size--;
    return true;
}

