private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // A subgraph induced by a single vertex or no vertices is trivially a clique
    if (vertices.size() <= 1) {
        return true;
    }

    // Check if every pair of vertices in the set is connected by an edge
    for (V vertex1 : vertices) {
        for (V vertex2 : vertices) {
            if (!vertex1.equals(vertex2) && !graph.containsEdge(vertex1, vertex2)) {
                return false;
            }
        }
    }

    return true;
}

