    Collections.sort(sortedKeys);

    for (K key : keys) {
        int index = Collections.binarySearch(sortedKeys, key);
        if (index < 0) {
            // If key is not found, binarySearch returns (-(insertion point) - 1)
            index = -index - 2; // Find the largest index less than the key
        }
        // If index is -1, it means all keys in sortedKeys are greater than the current key
        lowerBounds.add(index >= 0 ? sortedKeys.indexOf(sortedKeys.get(index)) : -1);
    }

    return lowerBounds;
}

